// checkedProductamd64256 returns the exact unsigned 128-bit product in two vectors.
// With B=2^32 and each limb < B, t <= B^2-B-1 and w1 <= B^2-B.
// Thus none of the intermediate carries are lost. The high half fits by definition.
func checkedProductamd64256(a, b archsimd.Uint64x4) (lo, hi archsimd.Uint64x4) {
	lowMask := archsimd.BroadcastUint64x4(0xffffffff)
	al, bl := a.ReshapeToUint32s(), b.ReshapeToUint32s()
	ah, bh := a.ShiftAllRight(32).ReshapeToUint32s(), b.ShiftAllRight(32).ReshapeToUint32s()
	w0 := al.MulWidenEven(bl)
	t := ah.MulWidenEven(bl).Add(w0.ShiftAllRight(32))
	w1 := t.And(lowMask).Add(al.MulWidenEven(bh))
	hi = ah.MulWidenEven(bh).Add(t.ShiftAllRight(32)).Add(w1.ShiftAllRight(32))
	lo = w1.ShiftAllLeft(32).Add(w0.And(lowMask))
	return
}

