func checkedamd64Uint64Mul256(left, right, out []uint64, validity, overflow memory.Bitmap) int {
	prepareIntegerArithmetic(len(left), len(left), len(right), len(out), overflow)
	if checkedIntegerPartialOverlap(left, right, out) {
		return scalarUint64Mul(left, right, out, validity, overflow)
	}
	first := -1
	for wi := 0; wi < memory.WordsFor(len(left)); wi++ {
		base := wi * 64
		rows := min(64, len(left)-base)
		validWord := bitmapWord(validity, wi) & memory.TailMask(rows)
		if validWord == 0 {
			clear(out[base : base+rows])
			continue
		}
		var failedWord uint64
		off := 0
		// Independent vectors amortize narrow backends' loop and bounds checks.
		for ; off+8 <= rows; off += 8 {
			leftBlock := left[base+off : base+off+8]
			rightBlock := right[base+off : base+off+8]
			outBlock := out[base+off : base+off+8]
			{
				laneOffset := off + 0
				a := archsimd.LoadUint64x4(leftBlock[0:])
				b := archsimd.LoadUint64x4(rightBlock[0:])
				result, hi := checkedProductamd64256(a, b)
				failed := hi.NotEqual(archsimd.Uint64x4{})
				failedWord |= uint64(failed.ToBits()) << uint(laneOffset)
				result.Store(outBlock[0:])
			}
			{
				laneOffset := off + 4
				a := archsimd.LoadUint64x4(leftBlock[4:])
				b := archsimd.LoadUint64x4(rightBlock[4:])
				result, hi := checkedProductamd64256(a, b)
				failed := hi.NotEqual(archsimd.Uint64x4{})
				failedWord |= uint64(failed.ToBits()) << uint(laneOffset)
				result.Store(outBlock[4:])
			}
		}
		for ; off+4 <= rows; off += 4 {
			laneOffset := off
			a := archsimd.LoadUint64x4(left[base+off:])
			b := archsimd.LoadUint64x4(right[base+off:])
			result, hi := checkedProductamd64256(a, b)
			failed := hi.NotEqual(archsimd.Uint64x4{})
			failedWord |= uint64(failed.ToBits()) << uint(laneOffset)
			result.Store(out[base+off:])
		}
		archsimd.ClearAVXUpperBits()
		for ; off < rows; off++ {
			row := base + off
			a, b := left[row], right[row]
			value := a * b
			hi, _ := bits.Mul64(a, b)
			failed := hi != 0
			if failed {
				failedWord |= uint64(1) << uint(off)
			}
			out[row] = value
		}
		failedWord &= validWord
		if overflow != nil {
			overflow[wi] = failedWord
		}
		if first < 0 && failedWord != 0 {
			first = base + bits.TrailingZeros64(failedWord)
		}
		invalid := ^validWord & memory.TailMask(rows)
		for invalid != 0 {
			lane := bits.TrailingZeros64(invalid)
			out[base+lane] = 0
			invalid &= invalid - 1
		}
	}
	return first
}

// checkedProductamd64512 returns the exact unsigned 128-bit product in two vectors.
// With B=2^32 and each limb < B, t <= B^2-B-1 and w1 <= B^2-B.
// Thus none of the intermediate carries are lost. The high half fits by definition.
func checkedProductamd64512(a, b archsimd.Uint64x8) (lo, hi archsimd.Uint64x8) {
	lowMask := archsimd.BroadcastUint64x8(0xffffffff)
	al, bl := a.And(lowMask), b.And(lowMask)
	ah, bh := a.ShiftAllRight(32), b.ShiftAllRight(32)
	w0 := al.Mul(bl)
	t := ah.Mul(bl).Add(w0.ShiftAllRight(32))
	w1 := t.And(lowMask).Add(al.Mul(bh))
	hi = ah.Mul(bh).Add(t.ShiftAllRight(32)).Add(w1.ShiftAllRight(32))
	lo = w1.ShiftAllLeft(32).Add(w0.And(lowMask))
	return
}

