func checkedamd64Int64Mul512(left, right, out []int64, validity, overflow memory.Bitmap) int {
	prepareIntegerArithmetic(len(left), len(left), len(right), len(out), overflow)
	if checkedIntegerPartialOverlap(left, right, out) {
		return scalarInt64Mul(left, right, out, validity, overflow)
	}
	first := -1
	for wi := 0; wi < memory.WordsFor(len(left)); wi++ {
		base := wi * 64
		rows := min(64, len(left)-base)
		validWord := bitmapWord(validity, wi) & memory.TailMask(rows)
		if validWord == 0 {
			clear(out[base : base+rows])
			continue
		}
		var failedWord uint64
		off := 0
		for ; off+8 <= rows; off += 8 {
			laneOffset := off
			a := archsimd.LoadInt64x8(left[base+off:])
			b := archsimd.LoadInt64x8(right[base+off:])
			au, bu := a.ToBits(), b.ToBits()
			lo, hi := checkedProductamd64512(au, bu)
			zero := archsimd.Uint64x8{}
			// Convert the unsigned product high half to the signed product high half.
			hi = hi.Sub(zero.Sub(au.ShiftAllRight(63)).And(bu)).Sub(zero.Sub(bu.ShiftAllRight(63)).And(au))
			// A signed product fits iff its high half is the sign extension of its low half.
			failed := hi.NotEqual(zero.Sub(lo.ShiftAllRight(63)))
			result := lo.BitsToInt64()
			failedWord |= uint64(failed.ToBits()) << uint(laneOffset)
			result.Store(out[base+off:])
		}
		archsimd.ClearAVXUpperBits()
		for ; off < rows; off++ {
			row := base + off
			a, b := left[row], right[row]
			value := a * b
			hi, _ := bits.Mul64(uint64(a), uint64(b))
			if a < 0 {
				hi -= uint64(b)
			}
			if b < 0 {
				hi -= uint64(a)
			}
			failed := hi != uint64(value>>63)
			if failed {
				failedWord |= uint64(1) << uint(off)
			}
			out[row] = value
		}
		failedWord &= validWord
		if overflow != nil {
			overflow[wi] = failedWord
		}
		if first < 0 && failedWord != 0 {
			first = base + bits.TrailingZeros64(failedWord)
		}
		invalid := ^validWord & memory.TailMask(rows)
		for invalid != 0 {
			lane := bits.TrailingZeros64(invalid)
			out[base+lane] = 0
			invalid &= invalid - 1
		}
	}
	return first
}

